package ru.neverland.townydiplomacy;

import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import ru.neverland.core.*;
import ru.neverland.townydiplomacy.aid.*;

public final class AidAuditSmoke {
    static int checks;static void check(boolean value,String text){if(!value)throw new AssertionError(text);checks++;}
    static <T>T done(CompletionStage<T> value)throws Exception{return value.toCompletableFuture().get(5,TimeUnit.SECONDS);}
    interface Attempt{void run()throws Exception;}static void fails(Attempt work,String text)throws Exception{try{work.run();}catch(Exception expected){checks++;return;}throw new AssertionError(text);}
    static boolean append(AuditJournal journal,AuditRecord receipt){try{journal.append(receipt);return true;}catch(Exception e){return false;}}
    public static void main(String[] args)throws Exception{
        var pact=AidSmoke.pact();var empty=AidState.empty();var signed=empty.put(pact,pact.firstMayor().toString(),"ACTIVATED",AidSmoke.NOW);var captured=AidAudit.capture(empty,signed,AidSmoke.NOW+1);var signature=captured.outbox().values().iterator().next();
        check(signature.at()==AidSmoke.NOW&&signature.operation().equals(pact.id().toString())&&signature.actor().id().equals(pact.firstMayor().toString()),"signature keeps exact signer, operation and original time");check(signature.from().id().equals(pact.first().toString())&&signature.to().id().equals(pact.second().toString())&&signature.kind().equals("DIPLOMACY_AID"),"common admin audit captures both parties and agreed kind");
        var root=Files.createTempDirectory("aid-audit-");var path=root.resolve("aid.yml");var audit=root.resolve("audit");Files.writeString(audit,"actual blocked audit directory");var journal=new AuditJournal(audit);var failed=new AidRepository(path,r->append(journal,r));done(failed.load());fails(()->done(failed.commit(empty,signed)),"actual audit directory failure rejects completion");
        check(!failed.writable()&&!failed.state().outbox().isEmpty()&&failed.state().pacts().containsKey(pact.id()),"failed audit retains durable action and exact outbox while closing new decisions");var preserved=AidRepository.read(path);check(preserved.equals(failed.state()),"audit failure cannot discard pending receipt from disk");fails(()->done(failed.commit(failed.state(),failed.state().neutral("pause"))),"audit failure never auto retries action");done(failed.closeAsync());
        Files.delete(audit);var recoveredJournal=new AuditJournal(audit);var replay=new AidRepository(path,r->append(recoveredJournal,r));var restored=done(replay.load());check(restored.outbox().isEmpty()&&restored.pacts().equals(signed.pacts()),"restart only drains audit outbox, without replaying a signature");check(replay.interruptedActivations().equals(Set.of(pact.id())),"activation with unfinished audit is marked for neutral restart validation");
        var lines=new ArrayList<AuditRecord>();AuditJournal.scan(audit,lines::add);check(lines.size()==1&&lines.get(0).equals(signature),"replayed receipt retains original timestamp and actor");done(replay.closeAsync());
        Files.writeString(path,AidRepository.encode(preserved));var again=new AidRepository(path,r->append(recoveredJournal,r));done(again.load());done(again.closeAsync());lines.clear();AuditJournal.scan(audit,lines::add);check(lines.size()==1,"journal ACK followed by snapshot failure cannot duplicate audit on replay");
        var attack=AidSmoke.fact(AidSmoke.E,AidSmoke.B,AidSmoke.B,AidSmoke.NOW+2000,2000);var opened=signed.observe(attack,Set.of(pact.id()));var call=opened.calls().values().iterator().next();var one=AidSmoke.fact(AidSmoke.A,AidSmoke.E,AidSmoke.B,AidSmoke.NOW+3000,5000);var two=AidSmoke.fact(AidSmoke.A,AidSmoke.E,AidSmoke.B,AidSmoke.NOW+9000,15000);var complete=call.observe(one).observe(two);var finished=new AidState(signed.pacts(),Map.of(call.id(),complete),signed.history());var changed=AidAudit.capture(opened,finished,AidSmoke.NOW+10_000);
        check(changed.outbox().size()==3,"every accepted fact plus completion gets separate audit even in one batch");check(changed.outbox().values().stream().filter(r->r.outcome().equals("PROGRESS")).count()==2&&changed.outbox().values().stream().anyMatch(r->r.outcome().equals("COMPLETED")&&r.at()==two.at()),"completion is attributed to original confirming fact and time");
        var neutral=AidAudit.capture(opened,opened.neutral("Administrative pause"),AidSmoke.NOW+11_000);check(neutral.outbox().values().stream().anyMatch(r->r.outcome().equals("UNASSESSED")&&r.details().contains("Administrative pause")),"neutral stop remains visible with reason");
        var latch=new CountDownLatch(1);var entered=new CountDownLatch(1);var delayed=new AidRepository(root.resolve("delayed.yml"),r->{entered.countDown();try{if(SuiteState.held())throw new AssertionError("audit owns SuiteState");latch.await();return true;}catch(InterruptedException e){Thread.currentThread().interrupt();return false;}});done(delayed.load());var saving=delayed.commit(empty,signed);check(entered.await(5,TimeUnit.SECONDS),"audit worker started after snapshot ACK");check(delayed.busy()&&!saving.toCompletableFuture().isDone()&&SuiteState.tryRun("audit smoke",()->{}),"delayed audit never blocks global shared state or reports completion");var close=delayed.closeAsync();check(!close.toCompletableFuture().isDone(),"shutdown waits accepted audit and subsequent outbox ACK");latch.countDown();done(saving);done(close);check(AidRepository.read(root.resolve("delayed.yml")).outbox().isEmpty(),"shutdown drains accepted receipt before writer closes");
        var yaml=new org.bukkit.configuration.file.YamlConfiguration();yaml.loadFromString(AidRepository.encode(signed));yaml.set("schema",1);yaml.set("audit-outbox",null);Files.writeString(path,yaml.saveToString());check(AidRepository.read(path).equals(signed),"old schema 1 keeps treaties, calls and history without fabricated receipts");
        check(!pact.phase(AidPact.Phase.FINALIZING,pact.accepter(),"Awaiting final check").live(AidSmoke.NOW+2000),"durable finalizing never activates before final rights validation");
        System.out.println("AidAuditSmoke PASS "+checks+" checks");
    }
}
